package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	if !scanner.Scan() {
		return
	}
	input := scanner.Text()
	if len(input) < 2 {
		return
	}

	seatChar := input[len(input)-1]
	rowStr := input[:len(input)-1]

	n, err := strconv.ParseInt(rowStr, 10, 64)
	if err != nil {
		return
	}

	// Determine block index k (0-based)
	// Blocks: 0: (1,3), 1: (2,4), 2: (5,7), 3: (6,8), 4: (9,11), ...
	// pattern: +1, +3, +1, +3, ...
	// block starts: 1, 2, 5, 6, 9, 10, ...
	// k even (0,2,4): start = 1 + (k/2)*4
	// k odd (1,3,5): start = 2 + (k/2)*4
	var k int64
	if n%2 == 1 { // odd row: 1,3,5,7,9,11...
		if n%4 == 1 { // 1,5,9... (Attendant 1 in even blocks)
			k = (n - 1) / 2 // integer division
			// n=1 -> k=0; n=5 -> k=2; n=9 -> k=4
		} else { // n%4 == 3: 3,7,11... (Attendant 2 in even blocks)
			k = (n - 3) / 2
			// n=3 -> k=0; n=7 -> k=2; n=11 -> k=4
		}
	} else { // even row: 2,4,6,8,10,12...
		if n%4 == 2 { // 2,6,10... (Attendant 1 in odd blocks)
			k = (n - 2) / 2 + 1
			// n=2 -> k=1; n=6 -> k=3; n=10 -> k=5
		} else { // n%4 == 0: 4,8,12... (Attendant 2 in odd blocks)
			k = (n - 4) / 2 + 1
			// n=4 -> k=1; n=8 -> k=3; n=12 -> k=5
		}
	}

	// Calculate time before block k starts
	// Even k (0,2): duration 6+1=7. Odd k (1,3): duration 6+3=9.
	// Pairs of blocks (0,1), (2,3) take 7+9=16 seconds.
	numPairs := k / 2
	timeBeforeBlock := numPairs * 16
	if k%2 == 1 {
		timeBeforeBlock += 7 // add duration of block 0 (even index)
	}

	// Determine position within block k
	// Block k serves rows: start and start+2
	// Attendant 1 serves row 'start', Attendant 2 serves row 'start+2'
	var blockStart int64
	if k%2 == 0 {
		blockStart = 1 + (k/2)*4
	} else {
		blockStart = 2 + (k/2)*4
	}

	var offsetInBlock int64
	if n == blockStart {
		// Attendant 1
		offsetInBlock = 0
	} else { // n == blockStart + 2
		// Attendant 2
		offsetInBlock = 7 // 6 seconds serving row blockStart + 1 second moving
	}

	// Seat order: f, e, d, a, b, c -> indices 1 to 6
	seatOrder := map[byte]int64{
		'f': 1,
		'e': 2,
		'd': 3,
		'a': 4,
		'b': 5,
		'c': 6,
	}
	seatTime := seatOrder[seatChar]

	totalTime := timeBeforeBlock + offsetInBlock + seatTime
	fmt.Println(totalTime)
}
